(() => {
'use strict';
const M=window.LabulaPrototypeModel;
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={menu:'<path d="m3 3 18 18M4 3v5a3 3 0 0 0 3 3h1m-1-8v4m3-4v5m9-5c-4 3-6 6-4 8l2 2m-6 2-8 8m15-8 4-4"/>',today:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18m-14 5 3 3 6-6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',back:'<path d="m12 5-7 7 7 7M5 12h15"/>',chevron:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',alert:'<path d="m12 3 10 18H2L12 3Z M12 9v5m0 3v.1"/>',settings:'<path d="M4 6h5m4 0h7M4 12h9m4 0h3M4 18h2m4 0h10"/><circle cx="11" cy="6" r="2"/><circle cx="15" cy="12" r="2"/><circle cx="8" cy="18" r="2"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',undo:'<path d="M4 10h9a6 6 0 0 1 0 12M4 10l5-5m-5 5 5 5"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7a2 2 0 0 0-5-5L4 15v5Z"/>',house:'<path d="m3 10 9-7 9 7M5 9v12h14V9M9 21v-8h6v8"/>',box:'<path d="m3 7 9-4 9 4v14H3V7Zm0 0h18M9 3v4"/>'};
const icon=(name,size=16)=>`<svg class="icon" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.menu}</svg>`;
const button=(text,action,id='',kind='secondary',extra='')=>`<button class="button ${kind}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''} ${extra}>${text}</button>`;
const storageKey='labula-composition-prototype-v1';
let data=M.seed(),drafts={},localAvailable=true,widgetAvailable=typeof window.openai?.setWidgetState==='function';
try{const saved=window.openai?.widgetState?.prototypeVersion===1?window.openai.widgetState:JSON.parse(localStorage.getItem(storageKey)||'null');if((saved?.version===1||saved?.prototypeVersion===1)&&saved.data?.entities){data=saved.data;drafts=saved.drafts||{};}}catch{localAvailable=false;}
let area='menu',tab='menu',todayView='evening',todaySelected=null,dialog=null,toastTimer=null,lastUndo=null,picker=null,mobileDetail=false;
const contexts={menu:{scope:'current',status:'all',category:'all',q:'',selected:[],root:'dish-s1-standard',trail:['dish-s1-standard'],onlySelected:false,pinned:[],scroll:0},house:{scope:'all',status:'all',category:'all',q:'',selected:[],root:'house-chilli-sauce',trail:['house-chilli-sauce'],onlySelected:false,pinned:[],scroll:0},ingredients:{scope:'current',status:'all',category:'all',q:'',selected:[],root:null,trail:[],onlySelected:false,pinned:[],scroll:0}};
const ctx=()=>contexts[tab];
const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const typeLabel=e=>e?.type==='dish'?'Menu dish':e?.type==='house'?'House-made':'Ingredient';
const entity=id=>data.entities[id];
const all=()=>Object.values(data.entities);
const compositionFields=e=>e?{inputs:e.inputs,notes:e.notes||'',confirmed:e.confirmed}:null;
const isDirty=id=>drafts[id]&&JSON.stringify(compositionFields(drafts[id].value))!==JSON.stringify(compositionFields(entity(id)));
const currentId=()=>ctx().trail.at(-1)||ctx().root;
const effective=id=>drafts[id]?{...entity(id),...compositionFields(drafts[id].value)}:entity(id);
const uniqueDishes=items=>new Set(items.map(e=>e.dishId||e.id)).size;
const uses=id=>M.activeUses(data,id);
const parents=id=>M.parents(data,id);
function persist(){const state={version:1,prototypeVersion:1,data,drafts};try{localStorage.setItem(storageKey,JSON.stringify(state));localAvailable=true;}catch{localAvailable=false;}if(widgetAvailable){try{const result=window.openai.setWidgetState(state);if(result?.catch)result.catch(()=>{widgetAvailable=false;});}catch{widgetAvailable=false;}}}
function commit(next){data=next;persist();}
function draft(id){if(!drafts[id])drafts[id]={value:M.clone(entity(id)),removed:null};return drafts[id];}
function notify(message,undo=false){clearTimeout(toastTimer);$('toasts').innerHTML=`<div class="toast">${icon('check')}<span>${esc(message)}</span>${undo?button('Undo','undo','','ghost small'):''}<button class="icon-button" data-action="dismiss-toast" aria-label="Dismiss">${icon('close')}</button></div>`;toastTimer=setTimeout(()=>$('toasts').innerHTML='',undo?16000:6500);}
function saveSnapshot(next,message){const previous=M.clone(data);commit(next);lastUndo={data:previous,revision:data.revision};notify(message,true);}
function ownLabel(e){return e.type==='ingredient'?'Bought':({empty:'Not started',draft:'Needs confirmation',confirmed:'Own list confirmed'}[M.ownState(e)]);}
function stateBadge(e,own=false){if(e.type==='ingredient')return '<span class="status-badge muted">Bought</span>';const done=own?M.ownState(e)==='confirmed':M.complete(data,e.id);const label=done?(own?'Confirmed':'Complete'):M.ownState(e)==='empty'?'Not started':M.ownState(e)==='confirmed'?(own?'Confirmed':'House-made to check'):'Needs confirmation';return `<span class="status-badge ${done?'good':'warn'}">${done?icon('check',12):icon('alert',12)}${label}</span>`;}
function inputName(id){return entity(id)?.name||'Unavailable ingredient';}
function displayName(e){return e.type==='dish'&&e.variant&&e.variant!=='Standard'?`${e.name} · ${e.variant}`:e.name;}
function tabItems(){return all().filter(e=>e.type===(tab==='menu'?'dish':tab==='house'?'house':'ingredient'));}
function matches(e,c=ctx()){
 if(c.onlySelected)return c.selected.includes(e.id);
 const used=e.type==='dish'?e.active:uses(e.id).length>0;
 if(c.scope==='current'&&!used||c.scope==='off'&&used)return false;
 if(c.category!=='all'&&(e.category||e.group)!==c.category)return false;
 if(c.status==='attention'&&M.complete(data,e.id)||c.status==='complete'&&!M.complete(data,e.id))return false;
 if(c.status==='own-attention'&&M.ownState(e)==='confirmed')return false;
 if(['empty','draft','confirmed'].includes(c.status)&&M.ownState(e)!==c.status)return false;
 const names=[e.name,e.variant,...(e.aliases||[]),...M.descendants(data,e.id).flatMap(id=>[entity(id)?.name,...(entity(id)?.aliases||[])])].filter(Boolean).join(' ');
 return normalize(names).includes(normalize(c.q));
}
function rows(){return tabItems().filter(e=>matches(e)||ctx().pinned.includes(e.id));}
function rememberScroll(){const el=document.querySelector('.table-scroll');if(el&&area==='menu')ctx().scroll=el.scrollTop;}
function selectTab(next){rememberScroll();tab=next;mobileDetail=false;if(!ctx().root||!entity(ctx().root)){const first=tabItems().find(e=>matches(e))||tabItems()[0];ctx().root=first?.id;ctx().trail=first?[first.id]:[];}render();}
function openRoot(id){rememberScroll();ctx().root=id;ctx().trail=[id];mobileDetail=true;render();if(matchMedia('(max-width: 559px)').matches)document.querySelector('.detail-header h2')?.focus();else if(matchMedia('(max-width: 759px)').matches)document.querySelector('.detail-panel')?.scrollIntoView({block:'nearest'});}
function openNested(id){rememberScroll();if(!entity(id))return;ctx().trail.push(id);renderDetail();document.querySelector('.detail-scroll')?.scrollTo(0,0);}
function openInMenu(id){area='menu';const e=entity(id);tab=e.type==='dish'?'menu':e.type==='house'?'house':'ingredients';if(!matches(e))ctx().pinned.push(id);openRoot(id);}
function render(){
 $('nav-menu').innerHTML=icon('menu',19)+'<span>Menu</span>';$('nav-today').innerHTML=icon('today',19)+'<span>Today</span>';$('settings-button').innerHTML=icon('settings')+'<span>Settings</span>';
 $('nav-menu').classList.toggle('active',area==='menu');$('nav-today').classList.toggle('active',area==='today');
 if(area==='today'){renderToday();return;}
 const c=ctx(),h=M.health(data),unconfirmedHouse=M.usedHouseMade(data).filter(e=>M.ownState(e)!=='confirmed');
 $('workspace').innerHTML=`<div class="page-heading"><h1>Menu</h1><nav class="subnav" aria-label="Menu views">${[['menu','Menu'],['house','House-made'],['ingredients','Ingredients']].map(([id,label])=>`<button data-action="tab" data-id="${id}" class="${tab===id?'active':''}" aria-current="${tab===id?'page':'false'}">${label}</button>`).join('')}</nav><div class="heading-actions">${button(icon('plus')+(tab==='menu'?'Add dish':tab==='house'?'Add house-made':'Add ingredient'),'new','','primary')}${button(icon('more'),'more','','ghost','aria-label="More actions"')}</div></div>
 <div class="health-bar" aria-label="Current menu composition"><button class="metric" data-action="health" data-id="complete"><b>${h.completeVariants}<span class="metric-denominator"> / ${h.activeVariants}</span></b><span>active variants complete<small>including house-made composition</small></span></button><button class="metric ${h.ownToCheck?'warn':''}" data-action="health" data-id="lists"><b>${h.ownToCheck}</b><span>dish lists to check<small>current menu</small></span></button><button class="metric ${unconfirmedHouse.length?'warn':''}" data-action="health" data-id="house"><b>${unconfirmedHouse.length}</b><span>house-made to complete<small>${uniqueDishes(M.activeRecipes(data).filter(e=>M.issues(data,e.id).some(i=>entity(i.id)?.type==='house')))} dishes affected</small></span></button><button class="metric" data-action="issues"><span class="metric-symbol">${icon('alert',18)}</span><span>Review issues<small>Start with the largest impact</small></span></button></div>
 <div class="workbench ${mobileDetail?'detail-open':''}"><section class="list-panel" aria-label="${tab==='menu'?'Menu variants':tab==='house'?'House-made':'Ingredients'}"><div class="list-toolbar"><label class="search-field">${icon('search')}<input id="table-search" type="search" placeholder="${tab==='menu'?'Search dishes, variants or ingredients…':tab==='house'?'Search house-made or ingredients…':'Search ingredients or aliases…'}" aria-label="Search list" value="${esc(c.q)}"><kbd>/</kbd></label><select class="filter-select" id="scope-filter" aria-label="Scope">${(tab==='menu'?[['current','Current menu'],['all','All dishes'],['off','Off menu']]:tab==='house'?[['all','All house-made'],['current','Used in current menu'],['off','Not in current menu']]:[['current','Used in current menu'],['all','All ingredients'],['off','Not in current menu']]).map(([value,label])=>`<option value="${value}" ${c.scope===value?'selected':''}>${label}</option>`).join('')}</select>${tab!=='ingredients'?`<select class="filter-select" id="status-filter" aria-label="Composition status">${[['all','Any composition'],['complete','Complete'],['attention','Needs attention'],['own-attention','Own list to check'],['empty','Not started'],['draft','Needs confirmation'],['confirmed','Own list confirmed']].map(([value,label])=>`<option value="${value}" ${c.status===value?'selected':''}>${label}</option>`).join('')}</select>`:''}${tab==='menu'?`<select class="filter-select category-filter" id="category-filter" aria-label="Category">${['all','Starters','Main Dishes','Specials'].map(value=>`<option ${c.category===value?'selected':''} value="${value}">${value==='all'?'All categories':value}</option>`).join('')}</select>`:''}</div><div class="list-caption" id="list-caption"></div><div class="table-scroll"><table class="data-table"><thead><tr><th class="check-cell"><input type="checkbox" id="select-all" aria-label="Select all filtered rows"></th><th class="name-cell">${tab==='menu'?'Dish / variant':tab==='house'?'House-made item':'Ingredient'}</th>${tab==='menu'?'<th class="category-cell">Category</th><th>Menu</th><th>Composition</th>':tab==='house'?'<th>Own composition</th><th>Current dishes</th><th>House-made uses</th>':'<th>Group</th><th>Current dishes</th><th>House-made uses</th>'}</tr></thead><tbody id="table-body"></tbody></table><div id="empty-list"></div></div><div class="selection-bar" id="selection-bar"></div></section><aside class="detail-panel" id="detail-panel" aria-label="Selected item details"></aside></div>`;
 renderRows();renderDetail();const scroller=document.querySelector('.table-scroll');if(scroller)scroller.scrollTop=c.scroll;
}
function renderRows(){if(area!=='menu')return;const c=ctx(),visible=rows();
 $('table-body').innerHTML=visible.map(e=>{const dishUses=uses(e.id),directParents=parents(e.id).filter(x=>x.type==='house'),pinned=c.pinned.includes(e.id)&&!matches(e);return `<tr class="${c.root===e.id?'selected':''}" data-row="${esc(e.id)}"><td class="check-cell"><input type="checkbox" data-select="${esc(e.id)}" aria-label="Select ${esc(displayName(e))}" ${c.selected.includes(e.id)?'checked':''}></td><td class="name-cell"><button class="row-open" data-action="open" data-id="${esc(e.id)}"><span class="row-title">${esc(e.name)}${isDirty(e.id)?'<span class="draft-dot" title="Unsaved changes"></span>':''}</span>${e.type==='dish'&&all().filter(x=>x.dishId===e.dishId&&x.type==='dish').length>1?`<span class="row-subtitle">${esc(e.variant||'Standard')}</span>`:''}${pinned?'<span class="row-subtitle held-row">Kept here after your change</span>':''}</button></td>${e.type==='dish'?`<td class="category-cell">${esc(e.category)}</td><td><button class="menu-state ${e.active?'on':''}" data-action="toggle-menu" data-id="${esc(e.id)}">${e.active?'On menu':'Off menu'}</button></td><td>${stateBadge(e)}</td>`:e.type==='house'?`<td>${stateBadge(e,true)}</td><td><span class="number">${uniqueDishes(dishUses)}</span>${dishUses.length!==uniqueDishes(dishUses)?`<small class="cell-secondary">${dishUses.length} variants</small>`:''}</td><td>${directParents.length||'—'}</td>`:`<td>${esc(e.group||'—')}</td><td>${uniqueDishes(dishUses)||'—'}</td><td>${directParents.length||'—'}</td>`}</tr>`;}).join('');
 const matching=visible.filter(e=>matches(e)).length;const count=tab==='menu'?`${matching} variants · ${uniqueDishes(visible.filter(e=>matches(e)))} dishes`:`${matching} ${tab==='house'?'house-made items':'ingredients'}`;
 $('list-caption').innerHTML=`<span>${count}${tab==='house'&&c.scope==='all'?` · ${M.usedHouseMade(data).length} used in current menu`:''}${c.onlySelected?' · selected items':''}</span><div>${c.pinned.length?button('Apply filters again','reapply','','ghost small'):''}${c.q||c.status!=='all'||c.category!=='all'||c.onlySelected?button('Reset filters','clear-filters','','ghost small'):''}${button('Export view','export','','ghost small')}</div>`;
 $('empty-list').innerHTML=visible.length?'':`<div class="empty-state">${icon('search',24)}<h3>No matching items</h3><p>Try another search or reset the filters.</p>${button('Reset filters','clear-filters')}</div>`;
 const selected=c.selected;const hidden=selected.filter(id=>!visible.some(e=>e.id===id)).length;
 $('selection-bar').hidden=!selected.length;
 $('selection-bar').innerHTML=selected.length?`<div class="selection-summary"><strong>${selected.length} selected</strong>${hidden?`<span>${hidden} outside this view</span>`:''}${button(c.onlySelected?'Show all results':'Show selected','show-selected','','ghost small')}${button('Clear','clear-selection','','ghost small')}</div><div class="selection-actions">${tab==='menu'?button('Set on menu','bulk','on','secondary small')+button('Set off menu','bulk','off','secondary small'):tab==='ingredients'?button('Change group','bulk-group','','secondary small'):button('Reopen lists','bulk','reopen','secondary small')}${button(icon('download')+'Export selected','export-selected','','secondary small')}</div>`:'';
 const allCheck=$('select-all');allCheck.checked=visible.length>0&&visible.every(e=>selected.includes(e.id));allCheck.indeterminate=visible.some(e=>selected.includes(e.id))&&!allCheck.checked;
}
function renderDetail(){if(area!=='menu')return;const id=currentId(),e=effective(id);const panel=$('detail-panel');if(!e){panel.innerHTML='<div class="empty-state"><h3>Select an item</h3><p>Its composition and usage will appear here.</p></div>';return;}
 const saved=entity(id),dirty=isDirty(id),issues=M.issues(data,id),ownIssues=issues.filter(i=>i.id===id),dependencyIssues=issues.filter(i=>i.id!==id),u=uses(id),p=parents(id);const breadcrumb=ctx().trail.map((entry,i)=>i===ctx().trail.length-1?`<span>${esc(entity(entry)?.name||'Item')}</span>`:`<button data-action="breadcrumb" data-id="${i}">${esc(entity(entry)?.name||'Item')}</button>${icon('chevron',12)}`).join('');
 panel.innerHTML=`<div class="detail-header"><button class="mobile-back button ghost small" data-action="back-list">${icon('back')}Back to list</button><div class="breadcrumbs">${breadcrumb||'Select an item'}</div><div class="detail-title-row"><div><p class="eyebrow">${typeLabel(e)}</p><h2 tabindex="-1">${esc(e.name)}</h2>${e.type==='dish'&&e.variant&&e.variant!=='Standard'?`<p class="detail-variant">${esc(e.variant)}</p>`:''}</div><button class="icon-button" data-action="metadata" data-id="${esc(id)}" aria-label="Edit name and details">${icon('edit')}</button></div><div class="detail-badges">${e.type==='ingredient'?'<span class="status-badge muted">Bought</span>':stateBadge(saved)}${e.type==='dish'?`<span class="status-badge muted">${e.active?'On menu':'Off menu'}</span>`:`<span class="detail-usage-count">${uniqueDishes(u)} current ${uniqueDishes(u)===1?'dish':'dishes'}</span>`}</div></div>
 <div class="detail-scroll">${e.type==='ingredient'?`<section class="detail-section"><p class="muted">Bought as an ingredient. No house-made recipe is needed.</p><dl class="metadata-list"><dt>Group</dt><dd>${esc(e.group||'Not assigned')}</dd><dt>Alternative names</dt><dd>${esc((e.aliases||[]).join(', ')||'None')}</dd></dl>${e.notes?`<p>${esc(e.notes)}</p>`:''}${button('Edit ingredient details','metadata',id,'secondary small')}</section>`:`<section class="detail-section"><div class="section-title"><h3>Composition</h3><span>${e.inputs.length} direct items</span></div>${e.type==='house'?`<p class="shared-hint">One shared item · changes apply in all ${uniqueDishes(u)} current ${uniqueDishes(u)===1?'dish':'dishes'}${p.filter(x=>x.type==='house').length?` and ${p.filter(x=>x.type==='house').length} house-made items`:''}.</p>`:''}<div class="composition-list">${e.inputs.map(part=>{const child=entity(part.id);return `<div class="composition-row"><span class="component-type ${child?.type==='house'?'house':''}">${icon(child?.type==='house'?'house':'box',15)}</span><div class="component-info"><button data-action="nested" data-id="${esc(part.id)}">${esc(child?.name||'Unavailable ingredient')}</button><small>${child?.type==='house'?'House-made · '+ownLabel(child):'Ingredient'}</small>${part.amount||part.note?`<span class="component-note">${esc([part.amount,part.note].filter(Boolean).join(' · '))}</span>`:''}</div><button class="remove-button icon-button" data-action="remove-input" data-id="${esc(part.id)}" aria-label="Remove ${esc(child?.name||'ingredient')} from this composition">${icon('close',14)}</button></div>`;}).join('')||'<div class="composition-empty"><p>No ingredients yet.</p><span>Add what goes into this item, then confirm the list.</span></div>'}</div>${button(icon('plus')+'Add ingredients','picker',id,'secondary add-ingredients')}${drafts[id]?.removed?button(icon('undo')+'Undo removal','undo-remove',id,'ghost small'):''}
 ${dirty?`<div class="notice">You are editing a draft. Save to update the menu overview.</div><label class="confirmation-field"><input type="checkbox" id="confirm-list" ${e.confirmed?'checked':''}>This list includes all ingredients</label>`:`<p class="own-state">${saved.confirmed?icon('check',14):icon('alert',14)}${ownLabel(saved)}</p>`}
 ${!dirty&&dependencyIssues.length?`<div class="notice warning"><strong>${dependencyIssues.length} ${dependencyIssues.length===1?'component needs':'components need'} attention</strong>${dependencyIssues.slice(0,4).map(i=>`<button class="issue-link" data-action="nested" data-id="${esc(i.id)}">${esc(inputName(i.id))}${icon('chevron',13)}<small>${esc(i.reason)}</small></button>`).join('')}</div>`:''}
 <details class="optional-details"><summary>Quantities & composition notes <span>optional</span></summary><p class="muted">Existing amounts and notes stay with each ingredient.</p>${e.inputs.map(part=>`<div class="quantity-row"><strong>${esc(inputName(part.id))}</strong><input aria-label="Amount for ${esc(inputName(part.id))}" data-amount="${esc(part.id)}" value="${esc(part.amount||'')}" placeholder="Amount, if known"><input aria-label="Note for ${esc(inputName(part.id))}" data-note="${esc(part.id)}" value="${esc(part.note||'')}" placeholder="Ingredient note"></div>`).join('')}<label class="form-field">Composition note<textarea rows="3" id="composition-note">${esc(e.notes||'')}</textarea></label></details>
 </section>`}
 ${e.type!=='dish'?renderUsage(id,p,u):`<section class="detail-section"><div class="section-title"><h3>Dish settings</h3></div><div class="detail-settings-actions">${button(e.active?'Set off menu':'Set on menu','toggle-menu',id,'secondary small')}${button(icon('plus')+'Add variant','variant',id,'ghost small')}</div><p class="muted">You can confirm a composition before putting it on the menu.</p></section>`}</div><div class="detail-footer" id="detail-footer"></div>`;
 renderFooter();
}
function renderUsage(id,p,u){const direct=p.filter(e=>e.type==='house'||e.type==='dish'&&e.active),inactive=p.filter(e=>e.type==='dish'&&!e.active),indirect=u.filter(e=>!p.some(parent=>parent.id===e.id));return `<section class="detail-section"><div class="section-title"><h3>Used in</h3><span>${uniqueDishes(u)} current ${uniqueDishes(u)===1?'dish':'dishes'}</span></div><div class="usage-list">${direct.map(e=>`<button class="usage-row" data-action="usage" data-id="${esc(e.id)}"><span>${esc(displayName(e))}<small>${e.type==='house'?'House-made · direct':'Menu dish · direct'}</small></span>${icon('chevron',13)}</button>`).join('')}${indirect.map(e=>`<button class="usage-row" data-action="usage" data-id="${esc(e.id)}"><span>${esc(displayName(e))}<small>Via house-made</small></span>${icon('chevron',13)}</button>`).join('')}${!direct.length&&!indirect.length?'<p class="muted">Not used in the current menu.</p>':''}</div>${inactive.length?`<details class="optional-details"><summary>${inactive.length} off-menu ${inactive.length===1?'variant':'variants'}</summary>${inactive.map(e=>`<button class="usage-row" data-action="usage" data-id="${esc(e.id)}">${esc(displayName(e))}${icon('chevron',13)}</button>`).join('')}</details>`:''}</section>`;}
function renderFooter(){const el=$('detail-footer');if(!el)return;const id=currentId(),e=effective(id);if(!e)return;const dirty=isDirty(id);el.innerHTML=`<div class="footer-state ${dirty?'pending':''}">${dirty?'Unsaved changes':localAvailable||widgetAvailable?'Saved in prototype':'Kept in this session'}${e.type==='house'&&dirty?`<small>Updates ${uniqueDishes(uses(id))} current dishes</small>`:''}</div><div class="footer-actions">${dirty?button('Discard','discard',id,'ghost small')+button('Save composition','save',id,'primary'):e.type!=='ingredient'&&!e.confirmed?button(icon('check')+'Confirm list','confirm',id,'primary',e.inputs.length?'':'disabled title="Add ingredients first"'):e.type!=='ingredient'?button('Next to complete','next','','secondary small'):''}</div>`;}
function showDialog(title,body,footer='',wide=false){dialog={title};$('dialogs').innerHTML=`<div class="dialog-backdrop"><section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="dialog-header"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-button" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></header><div class="dialog-body">${body}</div>${footer?`<footer class="dialog-footer">${footer}</footer>`:''}</section></div>`;setTimeout(()=>document.querySelector('.dialog input:not([type=checkbox]),.dialog button')?.focus(),0);}
function closeDialog(){dialog=null;$('dialogs').innerHTML='';document.querySelector('.detail-header h2')?.focus({preventScroll:true});}
function openPicker(id){picker={parent:id,q:'',type:'all',selected:[]};showDialog('Add ingredients',`<p class="muted">Choose existing ingredients or house-made items for <strong>${esc(entity(id).name)}</strong>.</p><div class="picker-search"><label class="search-field">${icon('search')}<input id="picker-query" type="search" placeholder="Name or alternative name…" aria-label="Search ingredients to add"></label><select class="filter-select" id="picker-type"><option value="all">All items</option><option value="house">House-made</option><option value="ingredient">Ingredients</option></select></div><div class="picker-results" id="picker-results"></div><div class="picker-create">Can't find it? ${button(icon('plus')+'Create new item','new-in-picker','','ghost small')}</div>`,button('Cancel','close-dialog','','ghost')+button('Add selected','add-picked','','primary','id="add-picked" disabled'),true);renderPicker();}
function renderPicker(){if(!picker||!$('picker-results'))return;const selected=effective(picker.parent).inputs.map(i=>i.id);const list=all().filter(e=>e.type!=='dish'&&e.id!==picker.parent&&(picker.type==='all'||e.type===picker.type)&&normalize([e.name,...(e.aliases||[])].join(' ')).includes(normalize(picker.q)));$('picker-results').innerHTML=list.map(e=>{const cycle=M.wouldCycle(data,picker.parent,e.id),added=selected.includes(e.id);return `<label class="picker-option ${cycle||added?'unavailable':''}"><input type="checkbox" data-pick="${esc(e.id)}" ${picker.selected.includes(e.id)||added?'checked':''} ${cycle||added?'disabled':''}><span class="component-type ${e.type==='house'?'house':''}">${icon(e.type==='house'?'house':'box',16)}</span><span><strong>${esc(e.name)}</strong><small>${typeLabel(e)}${e.type==='house'?' · '+ownLabel(e):''}</small></span>${added?'<small>Already added</small>':cycle?'<small>Would create a circular recipe</small>':''}</label>`;}).join('')||'<div class="empty-state"><p>No matching items.</p></div>';$('add-picked').disabled=!picker.selected.length;$('add-picked').textContent=picker.selected.length?`Add ${picker.selected.length} ${picker.selected.length===1?'item':'items'}`:'Add selected';}
function createDialog(kind,variantOf=null,fromPicker=false){const base=variantOf?entity(variantOf):null;const name=fromPicker?(picker?.q||''):'';showDialog(base?'Add variant':kind==='dish'?'Add dish':kind==='house'?'Add house-made item':'Add ingredient',`<form id="create-form" data-kind="${kind}" ${base?`data-parent="${esc(base.id)}"`:''} data-picker="${fromPicker}"><p class="muted">${base?'A new variant starts off menu.':kind==='dish'?'Start off menu, add the composition, then put it on the menu.':'Create once and reuse throughout the menu.'}</p><div class="form-grid"><label class="form-field">${base?'Variant name':kind==='dish'?'Dish name':'Item name'}<input id="new-name" name="name" required maxlength="160" value="${esc(name)}" placeholder="${base?'e.g. Vegetarian':kind==='house'?'e.g. Chilli sauce':'Name'}"></label>${kind!=='dish'?`<label class="form-field">Type<select name="type"><option value="ingredient" ${kind==='ingredient'?'selected':''}>Ingredient · bought</option><option value="house" ${kind==='house'?'selected':''}>House-made · made here</option></select></label>`:!base?'<label class="form-field">Category<select name="category"><option>Starters</option><option>Main Dishes</option><option>Specials</option></select></label>':''}</div><p id="form-error" class="form-error" role="alert"></p></form>`,button('Cancel','close-dialog','','ghost')+`<button class="button primary" type="submit" form="create-form">${fromPicker?'Create & add to draft':base?'Add variant':'Create item'}</button>`);}
function metadataDialog(id){const e=entity(id);showDialog('Edit details',`<form id="metadata-form" data-id="${esc(id)}"><div class="form-grid"><label class="form-field">Name<input name="name" value="${esc(e.name)}" required maxlength="160"></label>${e.type==='dish'?`<label class="form-field">Variant<input name="variant" value="${esc(e.variant||'Standard')}" required maxlength="160"></label><label class="form-field">Category<select name="category">${['Starters','Main Dishes','Specials'].map(c=>`<option ${e.category===c?'selected':''}>${c}</option>`).join('')}</select></label>`:`<label class="form-field">Alternative names<input name="aliases" value="${esc((e.aliases||[]).join(', '))}" placeholder="Separate with commas"></label>${e.type==='ingredient'?`<label class="form-field">Group<input name="group" value="${esc(e.group||'')}" placeholder="e.g. Vegetables"></label>`:''}`}</div><p class="muted">${e.type==='dish'?'Dish name and category are shared by its variants.':'This is one shared catalog item. Its identity stays the same.'}</p><p id="form-error" class="form-error" role="alert"></p></form>`,button('Cancel','close-dialog','','ghost')+'<button type="submit" form="metadata-form" class="button primary">Save details</button>');}
function bulkPreview(action,ids=ctx().selected){const list=[...new Set(ids)].map(entity).filter(Boolean);if(!list.length)return;const before=M.clone(data);let next=M.clone(data);for(const e of list){const patch=action==='reopen'?{confirmed:false}:{active:action==='on'};next=M.saveEntity(next,e.id,patch);}const affected=list.filter(e=>action==='reopen'?e.confirmed:e.active!==(action==='on'));const beforeActive=uniqueDishes(M.activeRecipes(data)),afterActive=uniqueDishes(M.activeRecipes(next));const rowsHtml=list.map(e=>`<div class="preview-row"><strong>${esc(displayName(e))}</strong><span>${action==='reopen'?e.confirmed?'Confirmed':'Open':e.active?'On menu':'Off menu'} ${icon('chevron',13)} <b>${action==='reopen'?'Open':action==='on'?'On menu':'Off menu'}</b></span></div>`).join('');showDialog(action==='reopen'?'Reopen ingredient lists':'Review menu change',`<p>${affected.length} of ${list.length} selected ${list.length===1?'item will':'items will'} change.</p>${action!=='reopen'?`<div class="notice">Current dishes: <strong>${beforeActive} → ${afterActive}</strong><br>Future checks follow the updated menu. A published morning plan keeps its confirmed work.</div>`:'<p class="muted">Existing ingredients and notes are kept. Only the list confirmation is reopened.</p>'}<div class="preview-list">${rowsHtml}</div>${action==='on'&&list.some(e=>!M.complete(next,e.id))?'<div class="notice warning">Some compositions still need attention. They will remain visible in the menu overview.</div>':''}`,button('Cancel','close-dialog','','ghost')+button(`Apply ${affected.length} ${affected.length===1?'change':'changes'}`,'apply-bulk','','primary',affected.length?'':'disabled'));dialog={...dialog,bulk:{next,before,ids:list.map(e=>e.id),revision:data.revision,action}};}
function exportRows(ids){const list=ids.map(entity).filter(Boolean),csvCell=v=>'"'+String(v??'').replaceAll('"','""')+'"';const records=[['Name','Variant','Type','On menu','Own list','Complete composition','Ingredients','Notes'],...list.map(e=>[e.name,e.variant||'',typeLabel(e),e.type==='dish'?e.active?'Yes':'No':'',ownLabel(e),e.type==='ingredient'?'':M.complete(data,e.id)?'Yes':'No',(e.inputs||[]).map(p=>[inputName(p.id),p.amount,p.note].filter(Boolean).join(' · ')).join('; '),e.notes])];const csv='\ufeff'+records.map(row=>row.map(csvCell).join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='labula-prototype-'+tab+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),3000);notify(`${list.length} rows exported from this prototype`);}
function showIssues(){const map=new Map();for(const e of M.activeRecipes(data))for(const issue of M.issues(data,e.id)){if(!map.has(issue.id))map.set(issue.id,{...issue,variants:new Set()});map.get(issue.id).variants.add(e.id);}const list=[...map.values()].sort((a,b)=>b.variants.size-a.variants.size);showDialog('Complete the menu composition',`<p class="muted">Fix a shared item once to improve every dish that uses it.</p><div class="issue-queue">${list.map(i=>`<button class="issue-queue-row" data-action="issue-open" data-id="${esc(i.id)}"><span>${icon(entity(i.id)?.type==='house'?'house':'menu',18)}</span><span><strong>${esc(inputName(i.id))}</strong><small>${esc(i.reason)}</small></span><span class="impact-count">${i.variants.size} ${i.variants.size===1?'variant':'variants'}${icon('chevron',14)}</span></button>`).join('')||'<div class="empty-state">All active menu compositions are complete.</div>'}</div>`,button('Close','close-dialog','','secondary'),true);}
function showGuide(){showDialog('Vyzkoušej si nový Workspace',`<div lang="cs"><p class="muted">Názvy jídel odpovídají LABULA. Receptury, kontroly a zásoby jsou ukázkové; vše měníš jen v prototypu.</p><div class="guide-grid">${[['sauce','1. Dokonči společnou omáčku','Otevři Chilli sauce, přidej surovinu a potvrď seznam. Sleduj změnu hodnocení jídel.'],['nested','2. Projdi složení do hloubky','Jídlo → omáčka → česneková pasta → ingredience. Zpět se vrátíš bez ztráty kontextu.'],['house','3. Najdi nepoužitý house-made','Všechny položky jsou v House-made, včetně těch mimo menu. Doplň si novou komponentu.'],['bulk','4. Vyzkoušej hromadnou změnu','Označ varianty, změň filtr a ověř skrytý výběr i náhled dopadu.'],['today','5. Přejdi z večera do rána','Označ stav sledovaných položek a zveřejni ukázkový ranní plán.'],['ingredients','6. Prozkoumej použití suroviny','Uvidíš přímé použití i jídla, ve kterých je surovina přes house-made.']].map(([id,title,text])=>`<button class="guide-card" data-action="guide-start" data-id="${id}"><strong>${title}</strong><p>${text}</p>${icon('chevron',16)}</button>`).join('')}</div><p class="muted">Rozpracované změny zůstávají při přepínání zachované. Tlačítkem Obnovit ukázku se kdykoli vrátíš na začátek. Today ukazuje směr budoucího sjednocení, ne finální pravidla plánování výroby.</p></div>`,button('Prohlédnout aplikaci','close-dialog','','primary'),true);}

function trackedItems(){return (data.tracked||[]).map(entity).filter(e=>e&&uses(e.id).length);}
function renderToday(){const list=trackedItems(),plan=data.plan,selected=entity(todaySelected)||list[0];todaySelected=selected?.id;const answered=list.filter(e=>data.checks[e.id]).length,low=list.filter(e=>data.checks[e.id]==='low'),tasks=plan?.tasks||[],ready=tasks.filter(t=>t.ready).length;
 $('workspace').innerHTML=`<div class="page-heading"><h1>Today</h1><nav class="subnav" aria-label="Daily work"><button data-action="today-tab" data-id="evening" class="${todayView==='evening'?'active':''}">Evening check</button><button data-action="today-tab" data-id="morning" class="${todayView==='morning'?'active':''}">Morning prep</button></nav><div class="heading-actions"><span class="date-label">17 Oct 2026 · example day</span>${button(icon('settings')+'Tracked items','tracking','','ghost small')}</div></div><div class="health-bar today-summary"><div class="metric"><b>${todayView==='evening'?answered:ready}<span class="metric-denominator"> / ${todayView==='evening'?list.length:tasks.length}</span></b><span>${todayView==='evening'?'items checked':'tasks ready'}<small>${todayView==='evening'?'Only explicitly tracked items':plan?'Published example plan':'No plan published yet'}</small></span></div><div class="metric"><b>${todayView==='evening'?low.length:tasks.length-ready}</b><span>${todayView==='evening'?'items need attention':'remaining tasks'}<small>${todayView==='evening'?'Prepare or restock':'Shared components appear once'}</small></span></div><div class="today-summary-note">${todayView==='evening'?'Check what you have. Publish what the morning needs.':plan?'This plan keeps the menu snapshot used when it was published.':'Publish an evening check to create a morning plan.'}</div></div>
 <div class="workbench today-layout ${mobileDetail?'detail-open':''}"><section class="list-panel"><div class="list-caption"><strong>${todayView==='evening'?'Evening check':'Morning prep'}</strong><span>${todayView==='evening'?'Current menu · tracked items':plan?'Published plan · demo':'Not published'}</span></div><div class="today-list">${todayView==='evening'?list.map(e=>`<div class="today-row ${todaySelected===e.id?'selected':''}"><button class="today-name" data-action="today-select" data-id="${esc(e.id)}"><span class="component-type ${e.type==='house'?'house':''}">${icon(e.type==='house'?'house':'box',17)}</span><span><strong>${esc(e.name)}</strong><small>${typeLabel(e)} · ${uniqueDishes(uses(e.id))} current ${uniqueDishes(uses(e.id))===1?'dish':'dishes'}</small></span></button><div class="today-actions"><button class="button ${data.checks[e.id]==='enough'?'answer-good':'secondary'}" data-action="check-enough" data-id="${esc(e.id)}">${icon('check')}Enough</button><button class="button ${data.checks[e.id]==='low'?'answer-low':'secondary'}" data-action="check-low" data-id="${esc(e.id)}">${e.type==='house'?'Needs prep':'Needs restock'}</button></div></div>`).join('')||'<div class="empty-state"><h3>No tracked items</h3><p>Choose which menu items the kitchen checks.</p></div>':plan?tasks.map(t=>`<div class="today-row ${t.ready?'task-ready':''}"><button class="today-name" data-action="today-select" data-id="${esc(t.id)}"><span class="component-type ${t.type==='house'?'house':''}">${icon(t.type==='house'?'house':'box',17)}</span><span><strong>${esc(t.name)}</strong><small>${t.type==='house'?'Prepare':'Restock'} · ${t.dishes.length} dishes at publication</small></span></button><div class="today-actions"><button class="button ${t.ready?'answer-good':'secondary'}" data-action="ready" data-id="${esc(t.id)}">${icon('check')}${t.ready?'Ready':'Mark ready'}</button></div></div>`).join('')||'<div class="empty-state"><h3>Nothing to prepare</h3><p>The published check marked all tracked items as enough.</p></div>':`<div class="empty-state">${icon('today',30)}<h3>The morning starts with a check</h3><p>Mark what is needed, then publish the example plan.</p>${button('Open evening check','today-tab','evening','primary')}</div>`}</div><div class="today-footer"><span>${todayView==='evening'?`${list.length-answered} unchecked · ${low.length} need attention`:plan?`${ready} of ${tasks.length} ready`:'No morning tasks yet'}</span>${todayView==='evening'?button('Review & publish plan','publish-plan','','primary',answered===list.length&&list.length?'':'disabled title="Check every tracked item first"'):button('Back to evening check','today-tab','evening','secondary')}</div></section><aside class="detail-panel">${selected?`<div class="detail-header"><button class="mobile-back button ghost small" data-action="back-list">${icon('back')}Back to list</button><p class="eyebrow">${typeLabel(selected)}</p><h2 tabindex="-1">${esc(selected.name)}</h2><div class="detail-badges">${stateBadge(selected)}<span class="detail-usage-count">${uniqueDishes(uses(selected.id))} current ${uniqueDishes(uses(selected.id))===1?'dish':'dishes'}</span></div></div><div class="detail-scroll"><section class="detail-section"><div class="section-title"><h3>${selected.type==='ingredient'?'Ingredient details':'Current composition'}</h3></div>${selected.type==='ingredient'?'<p class="muted">This ingredient is bought. Restocking is separate from house-made preparation.</p>':`<div class="composition-list">${selected.inputs.map(p=>`<div class="composition-row"><span class="component-type ${entity(p.id)?.type==='house'?'house':''}">${icon(entity(p.id)?.type==='house'?'house':'box',15)}</span><div class="component-info"><button data-action="issue-open" data-id="${esc(p.id)}">${esc(inputName(p.id))}</button><small>${typeLabel(entity(p.id))}</small></div></div>`).join('')}</div>`}<p class="muted">These ingredients explain the item. They do not become morning tasks automatically.</p></section>${renderUsage(selected.id,parents(selected.id),uses(selected.id))}</div><div class="detail-footer"><span class="footer-state">Shared item</span>${button('Open in Menu','issue-open',selected.id,'secondary small')}</div>`:'<div class="empty-state">Select an item</div>'}</aside></div>`;
}
function trackingDialog(){const items=[...M.usedHouseMade(data),...M.usedIngredients(data)];showDialog('Items included in evening checks',`<p class="muted">Choose what the kitchen actually checks. Composition ingredients are not added automatically.</p><div class="picker-results">${items.map(e=>`<label class="picker-option"><input type="checkbox" data-track="${esc(e.id)}" ${(data.tracked||[]).includes(e.id)?'checked':''}><span><strong>${esc(e.name)}</strong><small>${typeLabel(e)}</small></span></label>`).join('')}</div>`,button('Done','close-tracking','','primary'),true);}
function publishDialog(){const list=trackedItems(),low=list.filter(e=>data.checks[e.id]==='low');if(list.some(e=>!data.checks[e.id]))return;showDialog('Publish the example morning plan?',`<p>Only the ${low.length} tracked ${low.length===1?'item marked':'items marked'} as needed will become tasks.</p><div class="preview-list">${low.map(e=>`<div class="preview-row"><strong>${esc(e.name)}</strong><span>${e.type==='house'?'Prepare':'Restock'}</span></div>`).join('')||'<p>Everything is marked as enough. The plan will have no tasks.</p>'}</div><div class="notice">The plan keeps this menu snapshot. Later composition changes will not silently rewrite these tasks.</div>${data.plan?'<p class="muted">This replaces the previous example plan and resets its Ready marks.</p>':''}`,button('Back to check','close-dialog','','ghost')+button('Publish example plan','confirm-publish','','primary'));}

document.addEventListener('click',event=>{
 const target=event.target.closest('[data-action]');if(!target||target.disabled)return;const action=target.dataset.action,id=target.dataset.id;
 try{
 switch(action){
 case 'area':rememberScroll();area=id;mobileDetail=false;render();break;
 case 'tab':selectTab(id);break;
 case 'open':openRoot(id);break;
 case 'nested':openNested(id);break;
 case 'usage':openInMenu(id);break;
 case 'breadcrumb':ctx().trail=ctx().trail.slice(0,Number(id)+1);renderDetail();break;
 case 'back-list':mobileDetail=false;render();document.querySelector(`[data-row="${ctx().root}"] .row-open`)?.focus();break;
 case 'picker':openPicker(id);break;
 case 'add-picked':{const parent=picker.parent,d=draft(parent);for(const child of picker.selected)if(!d.value.inputs.some(p=>p.id===child))d.value.inputs.push({id:child,amount:'',note:''});d.value.confirmed=false;persist();closeDialog();render();break;}
 case 'remove-input':{const parent=currentId(),d=draft(parent),index=d.value.inputs.findIndex(p=>p.id===id);if(index<0)break;d.removed={part:M.clone(d.value.inputs[index]),index};d.value.inputs.splice(index,1);d.value.confirmed=false;persist();renderDetail();renderRows();break;}
 case 'undo-remove':{const d=drafts[id];if(!d?.removed)break;if(!d.value.inputs.some(p=>p.id===d.removed.part.id))d.value.inputs.splice(d.removed.index,0,d.removed.part);d.removed=null;persist();renderDetail();renderRows();break;}
 case 'save':{const e=drafts[id]?.value;if(!e)break;const next=M.saveEntity(data,id,compositionFields(e));delete drafts[id];ctx().pinned=[...new Set([...ctx().pinned,id])];commit(next);render();notify('Composition saved. Menu overview updated.');break;}
 case 'confirm':{const next=M.saveEntity(data,id,{confirmed:true});ctx().pinned=[...new Set([...ctx().pinned,id])];commit(next);render();notify('Own ingredient list confirmed');break;}
 case 'discard':delete drafts[id];persist();render();notify('Draft discarded. Saved composition kept.');break;
 case 'next':{const list=tabItems().filter(e=>e.type!=='ingredient'&&!M.complete(data,e.id));const index=list.findIndex(e=>e.id===currentId());const next=list[(index+1)%list.length];if(next){ctx().pinned.push(next.id);openRoot(next.id);}else notify('All compositions in this view are complete');break;}
 case 'metadata':metadataDialog(id);break;
 case 'new':createDialog(tab==='menu'?'dish':tab==='house'?'house':'ingredient');break;
 case 'variant':createDialog('dish',id);break;
 case 'new-in-picker':createDialog(picker?.type==='house'?'house':'ingredient',null,true);break;
 case 'toggle-menu':bulkPreview(entity(id).active?'off':'on',[id]);break;
 case 'bulk':bulkPreview(id);break;
 case 'apply-bulk':{const b=dialog.bulk;if(data.revision!==b.revision){notify('The example changed. Open the preview again.');closeDialog();break;}for(const affected of b.ids){ctx().pinned.push(affected);if(drafts[affected]&&b.action==='reopen')drafts[affected].value.confirmed=false;}saveSnapshot(b.next,'Group change applied');closeDialog();render();break;}
 case 'bulk-group':showDialog('Change ingredient group',`<form id="group-form"><p>${ctx().selected.length} selected ingredients, including items outside the current filter.</p><label class="form-field">Group<input name="group" placeholder="e.g. Vegetables" required maxlength="80"></label></form>`,button('Cancel','close-dialog','','ghost')+'<button form="group-form" type="submit" class="button primary">Save group</button>');break;
 case 'show-selected':ctx().onlySelected=!ctx().onlySelected;ctx().pinned=[];renderRows();break;
 case 'clear-selection':ctx().selected=[];ctx().onlySelected=false;renderRows();break;
 case 'reapply':ctx().pinned=[];renderRows();break;
 case 'clear-filters':Object.assign(ctx(),{scope:tab==='house'?'all':'current',status:'all',category:'all',q:'',onlySelected:false,pinned:[]});render();break;
 case 'health':area='menu';if(id==='house'){tab='house';Object.assign(ctx(),{scope:'current',status:'own-attention',q:'',category:'all',onlySelected:false,pinned:[]});}else{tab='menu';Object.assign(ctx(),{scope:'current',status:id==='lists'?'own-attention':'attention',q:'',category:'all',onlySelected:false,pinned:[]});}render();break;
 case 'issues':showIssues();break;
 case 'issue-open':closeDialog();openInMenu(id);break;
 case 'export':exportRows(rows().map(e=>e.id));break;
 case 'export-selected':exportRows(ctx().selected);break;
 case 'more':showDialog('Menu actions',`<div class="menu-actions">${button(icon('download')+'Export current view','export','','secondary')}${button(icon('alert')+'Review composition issues','issues','','secondary')}${button('How this prototype works','guide','','ghost')}</div>`,button('Close','close-dialog'));break;
 case 'undo':if(lastUndo&&lastUndo.revision===data.revision){const next=M.clone(lastUndo.data);next.revision=data.revision+1;commit(next);lastUndo=null;render();notify('Group change undone');}else notify('A newer change was saved. The earlier change can no longer be undone.');break;
 case 'dismiss-toast':$('toasts').innerHTML='';break;
 case 'close-dialog':closeDialog();break;
 case 'guide':showGuide();break;
 case 'guide-start':closeDialog();if(id==='sauce')openInMenu('house-chilli-sauce');else if(id==='nested'){area='menu';tab='menu';openRoot('dish-s1-standard');}else if(id==='house'){area='menu';selectTab('house');}else if(id==='bulk'){area='menu';tab='menu';ctx().selected=M.activeRecipes(data).slice(0,3).map(e=>e.id);render();}else if(id==='ingredients'){area='menu';openInMenu('ingredient-garlic');}else{area='today';todayView='evening';render();}break;
 case 'reset':showDialog('Obnovit ukázková data?',`<p lang="cs">Zruší se pouze změny a rozpracované návrhy v tomto prototypu. Skutečná aplikace LABULA se nemění.</p>`,button('Zpět','close-dialog','','ghost')+button('Obnovit ukázku','confirm-reset','','primary'));break;
 case 'confirm-reset':data=M.seed();drafts={};lastUndo=null;persist();for(const c of Object.values(contexts)){c.selected=[];c.pinned=[];c.onlySelected=false;c.q='';c.status='all';c.category='all';c.scroll=0;}contexts.menu.scope='current';contexts.house.scope='all';contexts.ingredients.scope='current';area='menu';tab='menu';ctx().root='dish-s1-standard';ctx().trail=[ctx().root];mobileDetail=false;closeDialog();render();notify('Ukázková data obnovena');break;
 case 'settings':showDialog('Workspace settings',`<p class="muted">This is an interactive design of LABULA Workspace 2.0.</p><dl class="metadata-list"><dt>Data</dt><dd>Illustrative compositions · real menu names</dd><dt>Changes</dt><dd>${localAvailable?'Saved only in this browser’s prototype storage':'Kept only in this session'}</dd><dt>Layout</dt><dd>Compact desktop · always-visible detail</dd><dt>Production</dt><dd>No connection to the live kitchen data</dd></dl><div class="notice">Use the guide to try the main workflows. Reset restores the example data.</div>`,button('Open guide','guide','','secondary')+button('Close','close-dialog','','primary'));break;
 case 'today-tab':todayView=id;mobileDetail=false;render();break;
 case 'today-select':todaySelected=id;mobileDetail=true;render();if(matchMedia('(max-width: 559px)').matches)document.querySelector('.detail-header h2')?.focus();else if(matchMedia('(max-width: 759px)').matches)document.querySelector('.detail-panel')?.scrollIntoView({block:'nearest'});break;
 case 'check-enough':case 'check-low':{const next=M.clone(data);next.checks[id]=action==='check-enough'?'enough':'low';next.revision++;commit(next);todaySelected=id;render();break;}
 case 'tracking':trackingDialog();break;
 case 'close-tracking':closeDialog();render();break;
 case 'publish-plan':publishDialog();break;
 case 'confirm-publish':{const next=M.clone(data);next.plan={sourceRevision:data.revision,publishedAt:new Date().toISOString(),tasks:trackedItems().filter(e=>data.checks[e.id]==='low').map(e=>({id:e.id,name:e.name,type:e.type,ready:false,inputs:M.clone(e.inputs),dishes:[...new Set(uses(e.id).map(x=>x.dishId||x.id))]}))};next.revision++;commit(next);closeDialog();todayView='morning';render();notify('Example morning plan published');break;}
 case 'ready':{const next=M.clone(data),task=next.plan?.tasks.find(t=>t.id===id);if(task){task.ready=!task.ready;next.revision++;commit(next);render();}break;}
 }
 }catch(error){notify(error.message||'The change could not be applied. Your draft is kept.');}
});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='table-search'){ctx().q=el.value;ctx().pinned=[];ctx().onlySelected=false;renderRows();}else if(el.id==='picker-query'){picker.q=el.value;renderPicker();}else if(el.dataset.amount||el.dataset.note){const id=currentId(),d=draft(id),part=d.value.inputs.find(p=>p.id===(el.dataset.amount||el.dataset.note));if(part){part[el.dataset.amount?'amount':'note']=el.value;persist();renderFooter();renderRows();}}else if(el.id==='composition-note'){draft(currentId()).value.notes=el.value;persist();renderFooter();renderRows();}});
document.addEventListener('change',event=>{const el=event.target;
 if(['scope-filter','status-filter','category-filter'].includes(el.id)){ctx()[el.id==='scope-filter'?'scope':el.id==='status-filter'?'status':'category']=el.value;ctx().pinned=[];ctx().onlySelected=false;renderRows();}
 else if(el.dataset.select){const c=ctx();c.selected=el.checked?[...new Set([...c.selected,el.dataset.select])]:c.selected.filter(id=>id!==el.dataset.select);renderRows();}
 else if(el.id==='select-all'){const ids=rows().map(e=>e.id);ctx().selected=el.checked?[...new Set([...ctx().selected,...ids])]:ctx().selected.filter(id=>!ids.includes(id));renderRows();}
 else if(el.id==='picker-type'){picker.type=el.value;renderPicker();}
 else if(el.dataset.pick){picker.selected=el.checked?[...new Set([...picker.selected,el.dataset.pick])]:picker.selected.filter(id=>id!==el.dataset.pick);renderPicker();}
 else if(el.id==='confirm-list'){draft(currentId()).value.confirmed=el.checked;persist();renderFooter();}
 else if(el.dataset.track){const next=M.clone(data);next.tracked=el.checked?[...new Set([...next.tracked,el.dataset.track])]:next.tracked.filter(id=>id!==el.dataset.track);next.revision++;commit(next);}
});
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target,values=new FormData(form);try{
 if(form.id==='create-form'){const parent=form.dataset.parent?entity(form.dataset.parent):null,type=parent?'dish':values.get('type')||form.dataset.kind,id=(type==='dish'?'dish':type==='house'?'house':'ingredient')+'-demo-'+Date.now().toString(36);const name=String(values.get('name')).trim();const e={id,type,name:parent?parent.name:name,variant:parent?name:type==='dish'?'Standard':undefined,dishId:parent?parent.dishId:type==='dish'?id:undefined,category:parent?.category||String(values.get('category')||''),active:false,confirmed:false,inputs:[],notes:'',aliases:[],group:''};const next=M.saveEntity(data,id,e);commit(next);if(form.dataset.picker==='true'&&picker){const d=draft(picker.parent);d.value.inputs.push({id,amount:'',note:''});d.value.confirmed=false;persist();closeDialog();render();notify('New shared item added to your draft');}else{closeDialog();openInMenu(id);notify('Created in the prototype');}}
 else if(form.id==='metadata-form'){const id=form.dataset.id,e=entity(id),name=String(values.get('name')).trim();let next=data;if(e.type==='dish'){for(const sibling of all().filter(x=>x.type==='dish'&&x.dishId===e.dishId)){next=M.saveEntity(next,sibling.id,{name,category:String(values.get('category')),...(sibling.id===id?{variant:String(values.get('variant')).trim()}:{})});if(drafts[sibling.id])Object.assign(drafts[sibling.id].value,{name,category:String(values.get('category')),...(sibling.id===id?{variant:String(values.get('variant')).trim()}:{})});}}else{const patch={name,aliases:String(values.get('aliases')||'').split(',').map(s=>s.trim()).filter(Boolean),...(e.type==='ingredient'?{group:String(values.get('group')||'')}:{})};next=M.saveEntity(next,id,patch);if(drafts[id])Object.assign(drafts[id].value,patch);}commit(next);closeDialog();render();notify('Shared details updated');}
 else if(form.id==='group-form'){let next=data;for(const id of ctx().selected)next=M.saveEntity(next,id,{group:String(values.get('group')).trim()});saveSnapshot(next,'Ingredient group updated');closeDialog();render();}
 }catch(error){const el=$('form-error');if(el)el.textContent=error.message;else notify(error.message);}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&dialog){event.preventDefault();closeDialog();}else if(event.key==='/'&&!dialog&&!['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName)){event.preventDefault();$('table-search')?.focus();}else if(dialog&&event.key==='Tab'){const focusable=[...document.querySelectorAll('.dialog button,.dialog input,.dialog select,.dialog textarea')].filter(el=>!el.disabled&&el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
window.addEventListener('beforeunload',persist);
window.addEventListener('openai:set_globals',event=>{const state=event.detail?.globals?.widgetState;if(state?.prototypeVersion===1&&state.data?.entities&&JSON.stringify(state.data)!==JSON.stringify(data)){data=M.clone(state.data);drafts=M.clone(state.drafts||{});render();}});
window.LabulaPrototype={getData:()=>M.clone(data),getDrafts:()=>M.clone(drafts),getContext:()=>({area,tab,context:M.clone(ctx())})};
render();
})();
